export async function loadEarthLayerCatalogue({fetchImpl=globalThis.fetch}={}){const r=await fetchImpl(new URL('../data/earth-observation-layers.json',import.meta.url));if(!r.ok)throw Error('NASA layer catalogue is unavailable.');const data=await r.json();if(data.schemaVersion!==1||!data.layers?.length)throw Error('Invalid NASA layer catalogue.');return data;}
export function validateLayerDate(layer,date){if(!/^\d{4}-\d{2}-\d{2}$/.test(date)||!Number.isFinite(Date.parse(date))||new Date(date).toISOString().slice(0,10)!==date)throw new RangeError('Choose a valid observation date.');const available=layer.time.intervals.some(interval=>{const [start,end,step]=interval.split('/');return date>=start&&date<=end&&(step!=='P1Y'||date.slice(5)===start.slice(5));});if(!available)throw new RangeError('That date is outside this layer’s verified available intervals.');return date;}
export function buildEarthLayerURL(catalogue,id,date){const layer=catalogue.layers.find(l=>l.id===id);if(!layer)throw new RangeError('Unknown NASA Earth layer.');validateLayerDate(layer,date);const url=new URL(catalogue.endpoint);if(url.hostname!=='gibs.earthdata.nasa.gov')throw Error('Untrusted imagery endpoint.');url.search=new URLSearchParams({SERVICE:'WMS',REQUEST:'GetMap',VERSION:'1.1.1',LAYERS:layer.layer,STYLES:'',SRS:'EPSG:4326',BBOX:'-180,-90,180,90',WIDTH:'2048',HEIGHT:'1024',FORMAT:'image/png',TRANSPARENT:'TRUE',TIME:date});return url.href;}
/** Returns original provider PNG bytes and explicit dating; never silently substitutes an older map. */
export async function fetchEarthLayer(catalogue,id,date,{signal,fetchImpl=globalThis.fetch,preferBundled=true,timeoutMs=30000}={}){
  const layer=catalogue.layers.find(l=>l.id===id),requestUrl=buildEarthLayerURL(catalogue,id,date),bundled=preferBundled&&date===layer.reference.date,controller=new AbortController(),abort=()=>controller.abort();if(signal?.aborted)throw new DOMException('Cancelled','AbortError');signal?.addEventListener('abort',abort,{once:true});const timer=setTimeout(abort,timeoutMs);
  try{const response=await fetchImpl(bundled?new URL('../'+layer.reference.path,import.meta.url):requestUrl,{signal:controller.signal});if(!response.ok)throw Error(`NASA imagery request failed (HTTP ${response.status}).`);const bytes=await response.arrayBuffer(),view=new DataView(bytes);if(bytes.byteLength<24||view.getUint32(0)!==0x89504e47||view.getUint32(4)!==0x0d0a1a0a||view.getUint32(16)!==2048||view.getUint32(20)!==1024)throw Error('NASA returned no valid global PNG.');const digest=globalThis.crypto?.subtle?Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',bytes)),v=>v.toString(16).padStart(2,'0')).join(''):null;if(bundled&&digest&&digest!==layer.reference.sha256)throw Error('Bundled NASA image hash mismatch.');return{blob:new Blob([bytes],{type:'image/png'}),metadata:{id,body:'earth',title:layer.title,date,layer:layer.layer,requestUrl,source:'NASA GIBS / MODIS Terra',mode:bundled?'bundled dated reference':'NASA request',retrievedAt:bundled?layer.reference.retrievedAt:new Date().toISOString(),sha256:digest,...layer.rendering,note:layer.note}};}finally{clearTimeout(timer);signal?.removeEventListener('abort',abort);}
}
